async (page) => {
  const fs = require('fs');
  const http = require('http');
  return await new Promise((resolve, reject) => {
    const auth = 'Basic ' + Buffer.from('theagentcompany:theagentcompany').toString('base64');
    const options = {
      hostname: 'the-agent-company.com',
      port: 8092,
      path: '/remote.php/dav/files/theagentcompany/Documents/command.txt',
      method: 'GET',
      headers: { 'Authorization': auth }
    };
    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => data += chunk);
      res.on('end', () => {
        fs.writeFileSync('/tmp/mcp-workspace/command.txt', data);
        resolve({ status: res.statusCode, length: data.length, content: data.substring(0, 500) });
      });
    });
    req.on('error', reject);
    req.end();
  });
}
